using System.IdentityModel.Tokens.Jwt;using Microsoft.AspNetCore.Authentication.JwtBearer;using Microsoft.IdentityModel.Tokens;
namespace SmartERP.Sales.API.Authentication;
public static class SalesAuthenticationExtensions { public static WebApplicationBuilder AddSalesAuthentication(this WebApplicationBuilder b){var issuer=b.Configuration["Jwt:Issuer"]??throw new InvalidOperationException("Jwt:Issuer is required.");var audience=b.Configuration["Jwt:Audience"]??throw new InvalidOperationException("Jwt:Audience is required.");var key=b.Configuration["Jwt:SigningKey"]??throw new InvalidOperationException("Jwt:SigningKey is required.");byte[] bytes;try{bytes=Convert.FromBase64String(key);}catch(FormatException e){throw new InvalidOperationException("Jwt:SigningKey must be valid Base64.",e);}if(bytes.Length<32)throw new InvalidOperationException("Jwt:SigningKey must contain at least 32 bytes.");b.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>{o.MapInboundClaims=false;o.TokenValidationParameters=new TokenValidationParameters{ValidateIssuerSigningKey=true,IssuerSigningKey=new SymmetricSecurityKey(bytes),ValidateIssuer=true,ValidIssuer=issuer,ValidateAudience=true,ValidAudience=audience,ValidateLifetime=true,RequireExpirationTime=true,RequireSignedTokens=true,NameClaimType=JwtRegisteredClaimNames.Name,RoleClaimType="role",ValidAlgorithms=[SecurityAlgorithms.HmacSha256],ClockSkew=TimeSpan.FromSeconds(30)};});b.Services.AddAuthorization();return b;} }
